import numpy as np

def feature(current, candidates, tour, start):
    """Distance from each candidate to the start, minus distance of current to start: a closure-aware nearest-neighbour measure."""
    d_start = np.linalg.norm(candidates - start[None, :], axis=1)
    d_cur_start = np.linalg.norm(current - start)
    return -(d_start - d_cur_start)

import numpy as np

def feature(current, candidates, tour, start):
    """Negative Euclidean distance from the current city to each candidate, scaled by 1/sqrt(2)."""
    return -np.linalg.norm(candidates - current, axis=1) / np.sqrt(2.0)

import numpy as np

def feature(current, candidates, tour, start):
    """Negative distance from each candidate to the start, scaled by how far the tour has already strayed from start."""
    d_start = np.linalg.norm(candidates - start, axis=1) / np.sqrt(2.0)
    # how far the current position is from start, normalised by the max possible distance
    stray = np.linalg.norm(current - start) / np.sqrt(2.0)
    # weight the start-proximity signal by the remaining "return pressure":
    # early in the tour (near start) the closing leg is cheap, so start-proximity matters less;
    # late in the tour it matters more. stray grows as the tour wanders away.
    return -d_start * (0.5 + 0.5 * stray)

import numpy as np

def feature(current, candidates, tour, start):
    """Cosine between the incoming travel direction and the step to each candidate (higher = straighter continuation)."""
    if tour.shape[0] < 2:
        return np.zeros(candidates.shape[0])
    dir = current - tour[-2]
    v = candidates - current
    nv = np.linalg.norm(v, axis=1)
    nd = np.linalg.norm(dir)
    cos = (v @ dir) / np.maximum(nv * nd, 1e-9)
    return np.clip(cos, -1.0, 1.0)

import numpy as np

def feature(current, candidates, tour, start):
    """Length of the mean unit vector from each candidate to all other remaining candidates (hull-vertex proxy)."""
    candidates = np.asarray(candidates, dtype=float)
    k = candidates.shape[0]
    if k < 3:
        return np.zeros(k)

    diff = candidates[None, :, :] - candidates[:, None, :]  # diff[i,j] = candidates[j]-candidates[i]
    d = np.sqrt(np.sum(diff * diff, axis=2))
    np.fill_diagonal(d, np.inf)
    u = diff / d[:, :, None]  # self term -> 0 since diff diagonal is 0
    resultant = np.sqrt(np.sum(np.sum(u, axis=1) ** 2, axis=1)) / (k - 1)
    return np.clip(resultant, 0.0, 1.0)

import numpy as np

def feature(current, candidates, tour, start):
    """Cosine of the angle between each candidate's step direction and the current->start bearing."""
    u = start - current
    r = np.linalg.norm(u)
    k = candidates.shape[0]
    if r < 1e-9:
        return np.zeros(k)
    u = u / r
    step = candidates - current
    d1 = np.linalg.norm(step, axis=1)
    return np.clip((step @ u) / (d1 + 1e-9), -1.0, 1.0)

import numpy as np

def feature(current, candidates, tour, start):
    """tanh((d_cur - d_start) / (nn + median(nn) + 0.02)): return-leg pull scaled by candidate local spacing."""
    k = len(candidates)
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    d_start = np.linalg.norm(candidates - start[None, :], axis=1)
    if k < 2:
        return np.zeros(k)
    D = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
    np.fill_diagonal(D, np.inf)
    nn = D.min(axis=1)
    scale = nn + np.median(nn) + 0.02
    return np.tanh((d_cur - d_start) / scale)

import numpy as np

def feature(current, candidates, tour, start):
    """(mean 3-NN spacing - distance to start) / (mean 3-NN spacing + distance to start)."""
    k = len(candidates)
    d_start = np.linalg.norm(candidates - start[None, :], axis=1)
    if k < 2:
        return np.zeros(k)
    D = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
    np.fill_diagonal(D, np.inf)
    kk = min(3, k - 1)
    spacing = np.partition(D, kk - 1, axis=1)[:, :kk].mean(axis=1)
    return (spacing - d_start) / (spacing + d_start + 1e-9)

