import numpy as np

def feature(current, candidates, tour, start):
    """Return-leg anticipation measured against the tour's own recent scale: (d_cur - d_start) divided by the mean leg length walked so far, so the pull toward start tightens as the tour's typical step shrinks."""
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    d_start = np.linalg.norm(candidates - start[None, :], axis=1)
    if tour.shape[0] >= 2:
        legs = np.linalg.norm(np.diff(tour, axis=0), axis=1)
        scale = legs.mean()
    else:
        scale = 0.0
    if scale < 1e-6:
        scale = np.sqrt(((candidates - current[None, :]) ** 2).sum(axis=1)).mean()
    if scale < 1e-6:
        scale = 0.5 * np.sqrt(2.0)
    return (d_cur - d_start) / scale

import numpy as np

def feature(current, candidates, tour, start):
    """Squared distance from candidate to the centroid of the unvisited set: which candidate sits at the core of what's left to visit."""
    candidates = np.asarray(candidates, dtype=float)
    k = candidates.shape[0]
    if k == 1:
        return np.zeros(1, dtype=float)
    centroid = candidates.mean(axis=0)
    d = np.linalg.norm(candidates - centroid[None, :], axis=1)
    # normalise: max possible distance in unit square is sqrt(2)/2 from centre
    return d / (0.5 * np.sqrt(2.0))

import numpy as np

def feature(current, candidates, tour, start):
    """Return-leg pull weighted by the candidate's distance to the current city relative to the tour's typical step length: (d_cur - d_start) * d_cur / mean_step."""
    d_cur = np.linalg.norm(candidates - current[None, :], axis=1)
    d_start = np.linalg.norm(candidates - start[None, :], axis=1)
    # typical step length so far (mean edge length of the visited chain)
    if tour.shape[0] >= 2:
        seg = np.linalg.norm(np.diff(tour, axis=0), axis=1)
        mean_step = float(seg.mean())
    else:
        mean_step = 0.0
    if mean_step < 1e-9:
        mean_step = 0.5 * np.sqrt(2.0)
    # amplify the return-leg signal for candidates that are also far from current
    return (d_cur - d_start) * (d_cur / mean_step) / (1.0 + d_cur / mean_step)

