import numpy as np

def feature(current, candidates, tour, start):
    """Standardised distance from the candidate to the centroid of the still-unvisited cities, measured relative to the current city's own radial position (tanh of the z-score of d_cand - d_current): high = candidate lies further out on the remaining rim than the current city, low = candidate sits deeper inside the remaining mass than the current city."""
    k = len(candidates)
    if k < 2:
        return np.zeros(k)
    cen = candidates.mean(axis=0)
    d = np.linalg.norm(candidates - cen[None, :], axis=1)
    d_cur = np.linalg.norm(current - cen)
    r = d - d_cur
    return np.tanh(r / (d.std() + 1e-9))

