import numpy as np

def feature(current, candidates, tour, start):
    """Unvisited-density kernel around each candidate: mean over the other unvisited cities of exp(-(d/R)^2), with R = 2 * median nearest-neighbour spacing of the unvisited set; high = the candidate still has many unvisited neighbours right next to it."""
    k = len(candidates)
    if k < 3:
        return np.zeros(k)
    dm = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
    np.fill_diagonal(dm, np.inf)
    R = 2.0 * np.median(dm.min(axis=1)) + 1e-9
    return np.exp(-(dm / R) ** 2).sum(axis=1) / (k - 1)

